mapper.select:
SELECT DATE_FORMAT(H.STATS_HR_DT,'%Y-%m-%d %H:00') AS timeLabel,
       MAX(CASE WHEN H.PERF_IDCT_CD='CPU_USGRT' THEN H.AVG_VL END) AS cpuVl,
       MAX(CASE WHEN H.PERF_IDCT_CD='MMRY_USGRT' THEN H.AVG_VL END) AS mmryVl
  FROM perf_hr_stats H
  JOIN eqpmnt_info E ON E.EQPMNT_SN=H.EQPMNT_SN AND E.USE_YN='Y'
 WHERE H.PERF_IDCT_CD IN ('CPU_USGRT','MMRY_USGRT')
   AND H.STATS_HR_DT >= #{startDt}
   AND H.STATS_HR_DT <= #{endDt}
   AND H.STATS_HR_DT >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
   AND E.LINK_SYS_CD=#{linkSysCd}
   AND E.STN_CD=#{stnCd}
   AND E.EQPMNT_SN=#{eqpmntSn}
 GROUP BY DATE_FORMAT(H.STATS_HR_DT,'%Y-%m-%d %H:00')
 ORDER BY MIN(H.STATS_HR_DT)
 LIMIT 48

