UPDATE clct_cycle_info SET CLCT_CYCLE_SEC=#{clctCycleSec}, STTS_MNTR_CYCLE_SEC=#{sttsMntrCycleSec},
       TIMEOUT_SEC=#{timeoutSec}, RTRY_NOCS=#{rtryNocs}, USE_YN=#{useYn}, MDFCN_DT=NOW(), MDFR_ID=#{mdfrId}
 WHERE CLCT_CYCLE_SN=#{clctCycleSn}
